head.script:
scwin.btn_Test_onclick = function() {
    var options = {
        "src": "dynamicCreate_WEF-105_(WSQ-2210)_popup_error.xml",
        "style": "position: absolute;top: 0;width: 100%;height:100%;z-index:9001"
    };
    WebSquare.layer.showModal();
    WebSquare.util.dynamicCreate("wfm_errAlert", "wframe", options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일 dynamicCreate_WEF-105_(WSQ-2210).xml을 실행 후 생성버튼을 클릭한다.
    //1. Run the sample file dynamicCreate_WEF-105_ (WSQ-2210) .xml and click the Generate button.
    //Verify step 1. The popup screen is normally displayed (previously an error occurred).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#btn_Test a')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_errAlert').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#_modal').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop	
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 20-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
